const src = $json.call || $json.data || $json;
const transcript = src.transcript || src.transcript_text || src.transcript_with_tool_calls || '';
const durationMs = src.duration_ms || ((src.end_timestamp && src.start_timestamp) ? Number(src.end_timestamp) - Number(src.start_timestamp) : null);
return [{json:{call_id:src.call_id || src.id || null,agent_id:src.agent_id || null,agent_name:src.agent_name || 'Retell Agent',transcript,recording_url:src.recording_url || src.recording_multi_channel_url || null,start_timestamp:src.start_timestamp || null,end_timestamp:src.end_timestamp || null,duration_ms:durationMs,disconnection_reason:src.disconnection_reason || null,raw_event_type:$json.event || $json.event_type || null}}];

const c=$json;
const instructions=`You are the independent TrueMate Voice Agent Supervisor. Audit ONLY the quality of the AI agent conversation, not GHL, CRM routing, or n8n automation. Review understanding, answer accuracy, listening, repetition, flow, naturalness, objection handling, closing, and safety/compliance. Never claim pronunciation, tone, overlap/interruption, silence, or voice quality is confirmed from transcript alone; instead set audio_review_needed=true. Status rules: HEALTHY 90-100, MONITOR 80-89, WARNING 65-79, CRITICAL below 65 or any critical failure. Critical failures include materially wrong/fabricated information, ignoring a clear stop/refusal, loops, misleading contradictions, or failing to answer a direct question in a materially harmful way. Findings require concrete evidence and confidence 0-100.`;
const input=`CALL ID: ${c.call_id || ''}
AGENT: ${c.agent_name || c.agent_id || ''}
DURATION_MS: ${c.duration_ms ?? ''}
DISCONNECTION: ${c.disconnection_reason || ''}
RECORDING_AVAILABLE: ${Boolean(c.recording_url)}

TRANSCRIPT:
${c.transcript}`;
return [{json:{...c,openai_body:{model:'gpt-5.5',store:false,instructions,input,text:{format:{type:'json_schema',name:'truemate_voice_qa',strict:true,schema:{type:'object',additionalProperties:false,properties:{overall_score:{type:'integer',minimum:0,maximum:100},status:{type:'string',enum:['HEALTHY','MONITOR','WARNING','CRITICAL']},critical:{type:'boolean'},audio_review_needed:{type:'boolean'},scores:{type:'object',additionalProperties:false,properties:{understanding:{type:'integer',minimum:0,maximum:100},answer_accuracy:{type:'integer',minimum:0,maximum:100},listening:{type:'integer',minimum:0,maximum:100},repetition:{type:'integer',minimum:0,maximum:100},flow:{type:'integer',minimum:0,maximum:100},naturalness:{type:'integer',minimum:0,maximum:100},objection_handling:{type:'integer',minimum:0,maximum:100},closing:{type:'integer',minimum:0,maximum:100},safety_and_compliance:{type:'integer',minimum:0,maximum:100}},required:['understanding','answer_accuracy','listening','repetition','flow','naturalness','objection_handling','closing','safety_and_compliance']},findings:{type:'array',items:{type:'object',additionalProperties:false,properties:{category:{type:'string'},severity:{type:'string',enum:['LOW','MEDIUM','HIGH','CRITICAL']},timestamp:{type:['string','null']},evidence:{type:'string'},explanation:{type:'string'},recommended_action:{type:'string'},confidence:{type:'integer',minimum:0,maximum:100}},required:['category','severity','timestamp','evidence','explanation','recommended_action','confidence']}},summary:{type:'string'}},required:['overall_score','status','critical','audio_review_needed','scores','findings','summary']}}},max_output_tokens:1800}}}];

const r=$json;
let text=r.output_text;
if(!text && Array.isArray(r.output)){for(const item of r.output){if(Array.isArray(item.content)){const t=item.content.find(x=>x.type==='output_text'&&x.text);if(t){text=t.text;break;}}}}
if(!text) throw new Error('OpenAI response did not contain output_text');
const qa=typeof text==='string'?JSON.parse(text):text;
return [{json:{audited_at:new Date().toISOString(),qa,openai_response_id:r.id || null}}];
